-- aar/w3/aar_row_648_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 648 (engine manual correction: the gemini debater reads the row gemini) and its ask_aar_builders row.
-- Every value is from W3's own write call (part 11.0 version 326, log row 346, audit 42222), Wall 12051, 12054, 12056, 12073, 12074, the card as stored in W3's thread, and md5sum by W3 of the files named.
-- A manual correction only: no engine, child or database object was changed.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (648, '0', $t$ASK 648: the engine manual says the gemini debater reads the row gemini, as the live engine does$t$,
  $t$Engine manual part 11.0 held the ASK 487 entry THE GEMINI DEBATER RUNS GEMINI 4 HYDROGEN, which said the gemini debater reads the row gemini_deb and runs the hydrogen model, and the ASK 482 entry said "gemini reads seat gemini_deb (ASK 487)". The live engine does not do that: Init Seats gives the gemini debater the row gemini, and the row gemini_deb is inactive and read by no node (W1, Wall 12051 and 12056). Change, in part 11.0 only: the ASK 487 entry is replaced by a shorter entry, THE GEMINI DEBATER READS THE SEAT gemini, and the one phrase in the ASK 482 entry is corrected. Expected effect: the manual states what the live engine does. No engine behaviour is changed.$t$,
  'yes',
  $t$Written by W3 at 08:24 CST 2026-11-25 on the operator's press "Write it" (08:23 CST) on W3's card: engine manual part 11.0, version 318 (cd5663e86d39507fc355e99717ec5f32, 38,108 characters) to version 326 (db2c50ca60851ad3db8fbadef563652f, 37,390), two literal replacements, each old text found once; engine_manual_log row 346 holds the removed ASK 487 entry whole (1,369 characters; file removed_648.txt e634697d); audit 42222 (Wall 12073). The written text equals the preview W1 graded (Wall 12056) and W1 read it back PASS (Wall 12074). YES, because the objective is the manual text itself and it is written and read back; no run is needed to show it. Deleted: the whole ASK 487 entry (heading and five sub-bullets). Changed: one phrase in the ASK 482 entry. NOT KNOWN to W3 from the record: which ASK took the gemini debater off gemini_deb; the new entry names none (W1 suggested ASK 623; not verified by W3). NOT CHECKED by W1: the sentence about stored rows of runs made under ASK 487. Open for the operator, outside this row: the gemini debater now runs the model of the row gemini, which is a flash model.$t$,
  '12051, 12054, 12056, 12073, 12074',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$No words of the operator on this defect were read by W3. The defect was found in the reading for the ASK 637 manual entry (W1, Wall 12051) and numbered by the coordinator. W3's write card (cmsg_017ZQamDMHrS6fqMHnQDVo589GcM1MmVP7CuRiRhHC2PoK, "Write the ASK 648 correction (gemini debater reads the row gemini) into the engine manual?"): he pressed "Write it" at 08:23 CST 2026-11-25.$t$::text),
  $j${"answer": "Write it", "question": "Write the ASK 648 correction (gemini debater reads the row gemini) into the engine manual?", "options": {"Write it": "I replace the stale ASK 487 entry with the short entry shown above and fix the one dashboard sentence. The deleted text is kept in the log row. W1 reads it back.", "Hold": "The manual keeps saying the gemini debater reads gemini_deb and runs hydrogen, which the live engine does not do."}, "thread": "W3", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo589GcM1MmVP7CuRiRhHC2PoK", "press_time": "08:23 CST 2026-11-25", "source": "W3's own card, re-read by W3, and the press delivered to W3's thread."}$j$::jsonb,
  'W3',
  $j${"md5": "d321a5d4516c499192e34560e332a81a", "path": "manual1123/w3/a648/em_pairs_648_draft1.json", "note": "no separate plan file: the two pairs are the plan and the change.", "source": "md5sum by W3"}$j$::jsonb,
  $j$[{"path": "manual1123/w3/a648/em_pairs_648_draft1.json", "md5": "d321a5d4516c499192e34560e332a81a", "what": "the two old and new texts written (commit 54205537 by Wall 12054)"}, {"path": "manual1123/w3/a648/removed_648.txt", "md5": "e634697d7831c9d6486857e9e7338a93", "what": "the removed ASK 487 entry, whole"}]$j$::jsonb,
  $j${"engine_manual": "parts are versioned and rows are kept; part 11.0 version 318 stands as its own row and log row 346 holds the removed text whole. Undo is a new version of part 11.0 holding the old text, on the operator's word.", "engine": "not written; nothing to revert", "rehearsed": "the two replacements were previewed on version 318 by W3 and reproduced by W1 (Wall 12056) before the card", "source": "W3's write call; Wall 12056"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS (pairs draft 1, file md5 d321a5d4; W1 reproduced the resulting text of part 11.0: 37,390 characters, the md5 given here)", "wall_id": 12056, "md5_graded": "db2c50ca60851ad3db8fbadef563652f", "verdict_norm": "PASS", "source": "Wall 12056"}]$j$::jsonb,
  ARRAY['db2c50ca60851ad3db8fbadef563652f'], '[42222]'::jsonb,
  $j$[{"kind": "table row", "name": "engine manual part 11.0", "before": "version 318, md5 cd5663e86d39507fc355e99717ec5f32, 38,108 characters", "after": "version 326, md5 db2c50ca60851ad3db8fbadef563652f, 37,390 characters (718 fewer); engine_manual_log row 346"}]$j$::jsonb,
  $j$[{"name": "Preview of the two replacements on version 318", "result": "each old text found once; result 37,390 characters, md5 db2c50ca; reproduced by W1", "source": "Wall 12054, 12056"}, {"name": "Checks inside the write call", "result": "pairs md5, section 0 md5, each old text found once (expects), result md5, no launch since odv1_launches id 104: all passed, or the call would have raised", "source": "W3's write call"}, {"name": "Search for gemini_deb", "result": "0 times in engine ee4e389d and child aad0ad9c, and in no public function or view; model_config gemini_deb inactive (W1)", "source": "Wall 12056"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS: 11.0 version 326, 37,390 characters, md5 db2c50ca, equal to the graded preview. NOT CHECKED: audit rows.", "wall_id": 12074, "source": "Wall 12074 (commit 8b7cc1bf)"}]$j$::jsonb,
  $j${"case": "NOT APPLICABLE: a manual correction; no engine behaviour changed.", "runs": [], "mark_for_the_next_run": "none", "not_shown": "nothing a run could show.", "source": "Wall 12054"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN: part 11.0 version 326, md5 db2c50ca60851ad3db8fbadef563652f, 37,390 characters, log row 346, audit 42222 (this row's own change)."}$j$::jsonb,
  'read back', $j$[12051, 12054, 12056, 12073, 12074]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W3'], $j$[{"seat": "W3", "what": "drafted the two pairs and wrote engine manual part 11.0 version 326 on the operator's card", "wall_id": 12073}]$j$::jsonb, current_setting('truth.session_id') FROM s;
